CREATE DATABASE IF NOT EXISTS smart_income_tax_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE smart_income_tax_db;
CREATE TABLE taxpayers (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(150) NOT NULL, pan CHAR(10) NOT NULL UNIQUE, age SMALLINT NOT NULL, email VARCHAR(254) NOT NULL, mobile CHAR(10) NOT NULL, residential_status VARCHAR(40) NOT NULL, financial_year VARCHAR(9) NOT NULL, tax_year VARCHAR(9) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_taxpayer_name(full_name));
CREATE TABLE income_details (id BIGINT PRIMARY KEY AUTO_INCREMENT, taxpayer_id BIGINT NOT NULL, financial_year VARCHAR(9) NOT NULL, salary DECIMAL(15,2) NOT NULL DEFAULT 0, house_property DECIMAL(15,2) NOT NULL DEFAULT 0, business DECIMAL(15,2) NOT NULL DEFAULT 0, capital_gains DECIMAL(15,2) NOT NULL DEFAULT 0, other_income DECIMAL(15,2) NOT NULL DEFAULT 0, FOREIGN KEY(taxpayer_id) REFERENCES taxpayers(id) ON DELETE CASCADE, INDEX idx_income_taxpayer_year(taxpayer_id,financial_year));
CREATE TABLE deductions (id BIGINT PRIMARY KEY AUTO_INCREMENT, taxpayer_id BIGINT NOT NULL, financial_year VARCHAR(9) NOT NULL, sec80c DECIMAL(15,2) NOT NULL DEFAULT 0, sec80d DECIMAL(15,2) NOT NULL DEFAULT 0, sec80g DECIMAL(15,2) NOT NULL DEFAULT 0, sec80e DECIMAL(15,2) NOT NULL DEFAULT 0, sec80tta DECIMAL(15,2) NOT NULL DEFAULT 0, sec80ccd1b DECIMAL(15,2) NOT NULL DEFAULT 0, other_deductions DECIMAL(15,2) NOT NULL DEFAULT 0, hra_exemption DECIMAL(15,2) NOT NULL DEFAULT 0, standard_deduction DECIMAL(15,2) NOT NULL DEFAULT 0, FOREIGN KEY(taxpayer_id) REFERENCES taxpayers(id) ON DELETE CASCADE, INDEX idx_deduction_taxpayer_year(taxpayer_id,financial_year));
CREATE TABLE tax_calculations (id BIGINT PRIMARY KEY AUTO_INCREMENT, taxpayer_id BIGINT NOT NULL, financial_year VARCHAR(9) NOT NULL, gross_income DECIMAL(15,2) NOT NULL, eligible_deductions DECIMAL(15,2) NOT NULL, old_tax DECIMAL(15,2) NOT NULL, new_tax DECIMAL(15,2) NOT NULL, recommended_regime VARCHAR(8) NOT NULL, calculation_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, snapshot_json JSON NOT NULL, FOREIGN KEY(taxpayer_id) REFERENCES taxpayers(id) ON DELETE CASCADE, INDEX idx_calc_taxpayer_year(taxpayer_id,financial_year));
CREATE TABLE tax_calculation_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, calculation_id BIGINT NOT NULL, taxpayer_id BIGINT NOT NULL, event_type VARCHAR(20) NOT NULL DEFAULT 'CREATED', event_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(calculation_id) REFERENCES tax_calculations(id) ON DELETE CASCADE, FOREIGN KEY(taxpayer_id) REFERENCES taxpayers(id) ON DELETE CASCADE, INDEX idx_history_taxpayer(taxpayer_id,event_at));
